// Get the output text from the Gemini node
const rawText = $input.first().json.content.parts[0].text;

let parsedData;
try {
  // Parse the stringified JSON from Gemini into a real JS object
  parsedData = typeof rawText === 'string' ? JSON.parse(rawText) : rawText;
} catch (error) {
  throw new Error("Gemini output was not valid JSON. Ensure 'Response MIME Type' is set to application/json in the Gemini node options.");
}

// Return as a single flat n8n item (which maps to a single row in Google Sheets)
return [
  {
    json: parsedData
  }
];
